%[text] # Report project statistics
%[text] This Live Script reports some statistics about the project. For information about MATLAB Project, see [Projects](https://www.mathworks.com/help/matlab/projects.html) in the documentation. For information about the  MATLAB Project object, see [`matlab.project.Project`](https://www.mathworks.com/help/matlab/ref/matlab.project.project.html).
% Make sure that a MATLAB Project is currently open.
assert(not(isempty(matlab.project.rootProject)), "No project is loaded.")

disp(currentProject().Name) %[output:4a6aa6ff]
%%
%[text] ### Project Paths
disp([currentProject().ProjectPath.StoredLocation]') %[output:21b395a2]
%[text] ### Startup Files
disp(extractAfter([currentProject().StartupFiles]', currentProject().RootFolder)) %[output:015a3b94]
%[text] ### Simulink cache folder
disp(extractAfter(currentProject().SimulinkCacheFolder, currentProject().RootFolder)) %[output:31122d6d]
%%
%[text] ## Files in Project
%[text] The number of files in the project
disp(numel(currentProject().Files) + " files") %[output:2accf8f6]
project_files = extractAfter([currentProject().Files.Path]', currentProject().RootFolder);
%[text] ### System Models
disp(project_files(contains(project_files, "system_model" + (".mdl"|".slx"), IgnoreCase=true))) %[output:5ce03cfe]
%[text] ### Referenced Subsystems
refsubs = project_files(contains(project_files, "_refsub.", IgnoreCase=true));
refsubs = refsubs(endsWith(refsubs, (".mdl"|".slx")));
disp(numel(refsubs) + " referenced subsystems") %[output:559db94f]
disp(refsubs) %[output:69f5c9d2]
%[text] ### Simscape custom components
sscfiles = project_files(endsWith(project_files, ".ssc"));
disp(numel(sscfiles) + " Simscape custom components") %[output:86517736]
disp(sscfiles) %[output:8a0ff20b]
%[text] ### Live Scripts
%[text] Use FileCollection to get the list of m files. In this case, files that are not registered with MATLAB project are captured too.
%[text] - [matlab.buildtool.io.FileCollection Class](https://www.mathworks.com/help/matlab/ref/matlab.buildtool.io.filecollection-class.html) \
mfile_pattern = fullfile(currentProject().RootFolder, "**/*.m");
mfile_collection = matlab.buildtool.io.FileCollection.fromPaths(mfile_pattern);
%[text] Apply a filter to get plain-text Live Scripts. See the documentation for [`select`](https://www.mathworks.com/help/matlab/ref/matlab.buildtool.io.filecollection.select.html).
live_script_file_collection = select(mfile_collection, @(p) bevutil1.FileUtil.isPlainTextLiveScript(p));
disp(numel(live_script_file_collection.paths) + " plain-text Live Scripts") %[output:31f6ab39]
live_script_paths = extractAfter(transpose(live_script_file_collection.paths), currentProject().RootFolder);
disp(live_script_paths) %[output:31b228c5]
%[text] ## buildfile.m files
buildfile_pattern = fullfile(currentProject().RootFolder, "**/buildfile.m");
buildfile_collection = matlab.buildtool.io.FileCollection.fromPaths(buildfile_pattern);
disp(numel(buildfile_collection.paths) + " buildfile.m files") %[output:9622a748]
buildfile_paths = extractAfter(transpose(buildfile_collection.paths), currentProject().RootFolder);
disp(buildfile_paths) %[output:1d6c855d]
